if (points.empty()) {
        return {};
    }

    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef K::Point_2 Point;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    typedef CGAL::Voronoi_diagram_2<DT> VD;

    DT dt;
    std::vector<Point> site_points;
    for (const auto& p : points) {
        site_points.emplace_back(p.x, p.y);
        dt.insert(p.x, p.y);
    }

    VD vd(dt);
    std::vector<std::vector<Point2d>> voronoi_cells(points.size());

    for (size_t i = 0; i < site_points.size(); ++i) {
        VD::Face_handle face = vd.locate(site_points[i]);
        if (face == nullptr) continue;

        std::vector<Point2d> cell_vertices;
        auto he = face->ccb();
        do {
            auto v = he->vertex();
            cell_vertices.emplace_back(v->point().x(), v->point().y());
            he = v->next();
        } while (he != face->ccb());

        voronoi_cells[i] = cell_vertices;
    }

    return voronoi_cells;

